script:
/* The native Messages page (chat_*.js). Sizes were measured from the old
   page, which uses frappe-ui: 13px text in the messages, 14px names, 28px
   controls, 8px and 12px radii. */

#cafe-chat {
  --c-outline: #ededed;
  --c-outline-2: #e2e2e2;
  --c-surface: #f3f3f3;
  --c-surface-1: #f8f8f8;
  --c-ink: #0f0f0f;
  --c-ink-6: #525252;
  --c-ink-5: #7c7c7c;
  --c-ink-4: #999999;
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  line-height: 1.15;
  color: var(--c-ink);
}
#cafe-chat *,
#cafe-chat *::before,
#cafe-chat *::after {
  box-sizing: border-box;
}
#cafe-chat button {
  cursor: pointer;
}
#cafe-chat [hidden],
.cafe-c-menu [hidden] {
  display: none !important;
}
.cafe-c-icon {
  display: inline-flex;
  flex-shrink: 0;
}
.cafe-c-icon svg {
  width: 100%;
  height: 100%;
}
.cafe-c-tiny {
  width: 14px;
  height: 14px;
}
.cafe-c-small {
  width: 16px;
  height: 16px;
}
.cafe-c-medium {
  width: 20px;
  height: 20px;
}
.cafe-c-faint {
  color: var(--c-ink-4);
}

/* ---- Two panes ---- */
.cafe-c-list {
  display: flex;
  flex: 0 0 320px;
  flex-direction: column;
  width: 320px;
  min-height: 0;
  border-right: 1px solid var(--c-outline);
}
.cafe-c-thread {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.cafe-c-pane {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
}
.cafe-c-empty-pane {
  display: grid;
  flex: 1;
  place-items: center;
  color: var(--c-ink-6);
}
.cafe-c-empty-pane p {
  margin: 0;
}

/* ---- Search box (the list, and the people dialogs) ---- */
.cafe-c-search {
  position: relative;
  flex-shrink: 0;
  padding: 12px;
  border-bottom: 1px solid var(--c-outline);
}
.cafe-c-search.dialog {
  padding: 0;
  border: 0;
}
.cafe-c-search-icon {
  position: absolute;
  top: 50%;
  left: 20px;
  width: 16px;
  height: 16px;
  transform: translateY(-50%);
  color: var(--c-ink-5);
  pointer-events: none;
}
.cafe-c-search.dialog .cafe-c-search-icon {
  left: 8px;
}
.cafe-c-search input,
.cafe-c-search-input {
  display: block;
  width: 100%;
  height: 28px;
  padding: 6px 8px 6px 32px;
  border: 1px solid var(--c-surface);
  border-radius: 8px;
  outline: none;
  background: var(--c-surface);
  color: #171717;
  font: inherit;
  font-size: 14px;
}
.cafe-c-search-input {
  padding-left: 8px;
}
.cafe-c-search input:hover,
.cafe-c-search-input:hover {
  background: #ededed;
  border-color: #ededed;
}
.cafe-c-search input:focus,
.cafe-c-search-input:focus {
  border-color: #999;
  background: #fff;
  box-shadow: 0 0 1px rgba(0, 0, 0, 0.2), 0 1px 3px rgba(0, 0, 0, 0.14);
}
.cafe-c-search input::placeholder,
.cafe-c-search-input::placeholder {
  color: var(--c-ink-5);
  opacity: 1;
}

/* ---- The list ---- */
.cafe-c-list-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.cafe-c-requests {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px;
  border: 0;
  border-bottom: 1px solid var(--c-outline);
  background: none;
  color: var(--c-ink-6);
  font-size: 13px;
  text-align: left;
}
.cafe-c-requests:hover,
.cafe-c-row:hover {
  background: var(--c-surface-1);
}
.cafe-c-requests-left,
.cafe-c-requests-right {
  display: flex;
  align-items: center;
  gap: 6px;
}
.cafe-c-requests .cafe-c-icon,
.cafe-c-requests-right .cafe-c-icon {
  width: 14px;
  height: 14px;
}
.cafe-c-unread {
  display: grid;
  flex-shrink: 0;
  place-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 4px;
  border-radius: 9999px;
  background: #171717;
  color: #fff;
  font-size: 11px;
  letter-spacing: 0.01em;
}
.cafe-c-row {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border: 0;
  background: none;
  text-align: left;
}
.cafe-c-row.active {
  background: var(--c-surface);
}
.cafe-c-row-text {
  flex: 1;
  min-width: 0;
}
.cafe-c-row-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.015em;
  line-height: 16.1px;
}
.cafe-c-row-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-row-handle {
  color: var(--c-ink-5);
  font-size: 12px;
  font-weight: 420;
}
.cafe-c-muted {
  width: 12px;
  height: 12px;
  color: var(--c-ink-4);
}
.cafe-c-row-preview {
  margin: 0;
  overflow: hidden;
  color: var(--c-ink-5);
  font-size: 13px;
  line-height: 14.95px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-empty {
  margin: 0;
  padding: 24px 16px;
  color: var(--c-ink-5);
  font-size: 13px;
  text-align: center;
}
.cafe-c-skeleton {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 12px;
}
.cafe-c-skeleton .cafe-skeleton {
  height: 40px;
  border-radius: 8px;
  background: linear-gradient(90deg, #f3f3f3, #fafafa, #f3f3f3);
  background-size: 200% 100%;
  animation: cafe-pulse 1.2s ease-in-out infinite;
}

/* ---- Avatars ---- */
.cafe-c-avatar {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border-radius: 9999px;
  background: var(--c-surface);
  color: var(--c-ink-5);
  font-weight: 500;
  text-transform: uppercase;
}
.cafe-c-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cafe-c-avatar-md {
  width: 24px;
  height: 24px;
  font-size: 14px;
}
.cafe-c-avatar-sm {
  width: 20px;
  height: 20px;
  font-size: 13px;
}
.cafe-c-avatar-xs {
  width: 16px;
  height: 16px;
  font-size: 10px;
}

/* ---- Thread header ---- */
.cafe-c-head {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 53px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--c-outline);
}
.cafe-c-head-left {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
}
.cafe-c-head-name {
  min-width: 0;
}
.cafe-c-head-link,
.cafe-c-head-title {
  display: block;
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.015em;
  line-height: 16.1px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-typing {
  color: var(--c-ink-5);
  font-size: 12px;
  line-height: 14px;
}
.cafe-c-head-right {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
}
.cafe-c-head-search {
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: none;
  color: var(--c-ink-5);
}
.cafe-c-head-search:hover {
  color: var(--c-ink);
}
.cafe-c-more-btn {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: var(--c-surface);
  color: #171717;
}
.cafe-c-more-btn:hover {
  background: #ededed;
}
.cafe-c-back {
  display: none;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: 0;
  background: none;
}
.cafe-c-search-host {
  padding: 12px;
  border-bottom: 1px solid var(--c-outline);
}
.cafe-c-hits {
  margin-top: 8px;
}
.cafe-c-hit {
  display: block;
  width: 100%;
  padding: 4px 8px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--c-ink-6);
  font-size: 13px;
  text-align: left;
}
.cafe-c-hit:hover {
  background: var(--c-surface-1);
}
.cafe-c-hit-name {
  color: var(--c-ink);
  font-weight: 500;
}
.cafe-c-hit-none {
  margin: 8px 0 0;
  color: var(--c-ink-5);
  font-size: 13px;
}
.cafe-c-banner {
  flex-shrink: 0;
  padding: 8px 16px;
  border-bottom: 1px solid var(--c-outline);
  background: #fff7d3;
  color: var(--c-ink-6);
  font-size: 13px;
}
.cafe-c-banner.request {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.cafe-c-banner-actions {
  display: flex;
  flex-shrink: 0;
  gap: 8px;
}

/* ---- Messages ---- */
.cafe-c-messages {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 24px 16px 12px;
}
.cafe-c-message-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.cafe-c-msg {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.cafe-c-msg.own {
  flex-direction: row-reverse;
}
.cafe-c-msg-col {
  min-width: 0;
  max-width: 70%;
  font-size: 13px;
  line-height: 14.95px;
}
.cafe-c-msg-col.fit {
  width: fit-content;
}
.cafe-c-bubble {
  position: relative;
  padding: 8px 12px;
  border-radius: 12px;
  background: var(--c-surface);
  transition: background-color 0.5s;
  overflow-wrap: anywhere;
}
.cafe-c-msg.flash .cafe-c-bubble {
  background: #fff7d3;
}
.cafe-c-deleted {
  color: var(--c-ink-5);
  font-style: italic;
}
.cafe-c-plain {
  white-space: pre-wrap;
}
.cafe-c-inline-code,
.cafe-c-html code {
  padding: 0 4px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.1);
  font-size: 12px;
}
.cafe-c-plain a,
.cafe-c-html a {
  text-decoration: underline;
}
.cafe-c-html {
  font-size: 14px;
  line-height: 1.5;
}
.cafe-c-html > :first-child {
  margin-top: 0;
}
.cafe-c-html > :last-child {
  margin-bottom: 0;
}
.cafe-c-html p {
  margin: 0;
}
.cafe-c-html ul,
.cafe-c-html ol {
  margin: 4px 0;
  padding-left: 20px;
}
.cafe-c-html ul {
  list-style: disc;
}
.cafe-c-html ol {
  list-style: decimal;
}
.cafe-c-html blockquote {
  margin: 4px 0;
  padding-left: 10px;
  border-left: 2px solid #c2c2c2;
}
.cafe-c-html pre {
  margin: 4px 0;
  padding: 8px 10px;
  overflow-x: auto;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.08);
  font-size: 12px;
}
.cafe-c-html pre code {
  padding: 0;
  background: none;
}
.cafe-c-html mark {
  background: #ffe97a;
}
.cafe-c-html .mention,
.cafe-c-prose .mention {
  padding: 0 4px;
  border-radius: 4px;
  background: #e2f0fd;
  color: #0b62c4;
  font-weight: 500;
}
.cafe-c-reply-preview {
  display: block;
  width: 100%;
  margin-bottom: 6px;
  padding: 4px 8px;
  border: 0;
  border-left: 2px solid var(--c-ink-4);
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.05);
  text-align: left;
}
.cafe-c-reply-name,
.cafe-c-reply-text {
  overflow: hidden;
  font-size: 12px;
  line-height: 13.8px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-reply-name {
  color: #383838;
  font-weight: 500;
}
.cafe-c-reply-text {
  color: var(--c-ink-5);
}
.cafe-c-time {
  margin-top: 2px;
  color: var(--c-ink-4);
  font-size: 12px;
  line-height: 13.8px;
}
.cafe-c-msg.own .cafe-c-time,
.cafe-c-seen {
  text-align: right;
}
.cafe-c-seen {
  color: var(--c-ink-4);
  font-size: 12px;
  line-height: 13.8px;
}
.cafe-c-reactions {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}
.cafe-c-msg.own .cafe-c-reactions {
  justify-content: flex-end;
}
.cafe-c-reaction {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border: 1px solid var(--c-outline);
  border-radius: 9999px;
  background: none;
  font-size: 12px;
}
.cafe-c-reaction.mine {
  border-color: #c2c2c2;
  background: var(--c-surface);
}

/* The three buttons on a message: react, reply, more. */
.cafe-c-hover {
  display: contents;
}
.cafe-c-hover-btn {
  position: absolute;
  top: -12px;
  display: none;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid var(--c-outline);
  border-radius: 9999px;
  background: #fff;
  color: var(--c-ink-6);
}
.cafe-c-bubble:hover .cafe-c-hover-btn {
  display: grid;
}
.cafe-c-hover.own .cafe-c-hover-btn:nth-child(1) { left: -12px; }
.cafe-c-hover.own .cafe-c-hover-btn:nth-child(2) { left: -40px; }
.cafe-c-hover.own .cafe-c-hover-btn:nth-child(3) { left: -64px; }
.cafe-c-hover.other .cafe-c-hover-btn:nth-child(1) { right: -12px; }
.cafe-c-hover.other .cafe-c-hover-btn:nth-child(2) { right: -40px; }
.cafe-c-hover.other .cafe-c-hover-btn:nth-child(3) { right: -64px; }

/* Pictures, files and cards in a message */
.cafe-c-attachments {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}
.cafe-c-attachments.grid {
  width: 230px;
}
.cafe-c-picture {
  position: relative;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 4px;
  background: none;
  line-height: 0;
}
.cafe-c-picture img {
  max-height: 256px;
  border-radius: 4px;
  object-fit: cover;
}
.cafe-c-attachments.grid .cafe-c-picture {
  width: 112px;
  height: 112px;
}
.cafe-c-attachments.grid .cafe-c-picture img {
  width: 100%;
  height: 100%;
  max-height: none;
}
.cafe-c-more {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  font-size: 18px;
  font-weight: 500;
  line-height: 1;
}
.cafe-c-file {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border: 1px solid var(--c-outline-2);
  border-radius: 8px;
  background: #fff;
  color: #171717;
  font-size: 12px;
  text-decoration: none;
}
.cafe-c-file:hover {
  background: var(--c-surface-1);
}
.cafe-c-file .cafe-c-icon {
  width: 14px;
  height: 14px;
  color: var(--c-ink-5);
}
.cafe-c-file-name {
  max-width: 128px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-post-card {
  display: flex;
  width: 256px;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
  padding: 8px;
  overflow: hidden;
  border: 1px solid var(--c-outline);
  border-radius: 8px;
  background: #fff;
  text-decoration: none;
}
.cafe-c-post-card img {
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  border-radius: 4px;
  object-fit: cover;
}
.cafe-c-card-text {
  min-width: 0;
}
.cafe-c-card-title {
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-card-desc {
  display: block;
  margin: 0;
  overflow: hidden;
  color: var(--c-ink-5);
  font-size: 12px;
  line-height: 16px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-link-card {
  display: block;
  margin-top: 8px;
  overflow: hidden;
  border: 1px solid var(--c-outline);
  border-radius: 4px;
  text-decoration: none;
}
.cafe-c-link-card img {
  display: block;
  width: 100%;
  height: 112px;
  object-fit: cover;
}
.cafe-c-link-text {
  padding: 8px;
}
.cafe-c-link-title {
  overflow: hidden;
  font-size: 12px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-link-desc {
  display: -webkit-box;
  margin: 2px 0 0;
  overflow: hidden;
  font-size: 12px;
  line-height: 16px;
  opacity: 0.8;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}
.cafe-c-poll {
  width: 288px;
  max-width: 100%;
  margin-top: 8px;
  padding: 12px;
  border: 1px solid var(--c-outline-2);
  border-radius: 8px;
  background: #fff;
}
.cafe-c-poll-question {
  font-size: 14px;
  font-weight: 500;
  line-height: 16px;
}
.cafe-c-poll-options {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 10px;
}
.cafe-c-poll-option {
  position: relative;
  width: 100%;
  overflow: hidden;
  padding: 6px 10px;
  border: 1px solid var(--c-outline-2);
  border-radius: 6px;
  background: none;
  font-size: 14px;
  text-align: left;
}
.cafe-c-poll-option:disabled {
  cursor: default;
}
.cafe-c-poll-bar {
  position: absolute;
  inset: 0 auto 0 0;
  background: var(--c-surface);
}
.cafe-c-poll-line {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.cafe-c-poll-label {
  display: flex;
  align-items: center;
  gap: 6px;
  color: #171717;
}
.cafe-c-poll-label .cafe-c-icon {
  width: 14px;
  height: 14px;
}
.cafe-c-poll-count {
  flex-shrink: 0;
  color: var(--c-ink-5);
  font-size: 12px;
}
.cafe-c-poll-foot {
  margin-top: 8px;
  color: var(--c-ink-5);
  font-size: 12px;
}

/* ---- Composer ---- */
.cafe-c-composer-host {
  flex-shrink: 0;
  padding: 12px;
  border-top: 1px solid var(--c-outline);
}
.cafe-c-box {
  border: 1px solid var(--c-outline-2);
  border-radius: 12px;
  background: #fff;
}
.cafe-c-box:focus-within {
  border-color: #999;
}
.cafe-c-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--c-outline);
}
.cafe-c-bar-text {
  min-width: 0;
  flex: 1;
}
.cafe-c-bar-title {
  color: #383838;
  font-size: 12px;
  font-weight: 500;
}
.cafe-c-bar-preview {
  overflow: hidden;
  color: var(--c-ink-5);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-icon-btn {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--c-ink-5);
}
.cafe-c-icon-btn:hover {
  background: var(--c-surface);
  color: #171717;
}
.cafe-c-pendings {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 8px 0;
}
.cafe-c-pending {
  display: flex;
  width: 224px;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--c-outline-2);
  border-radius: 8px;
}
.cafe-c-pending-thumb {
  display: grid;
  flex-shrink: 0;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9999px;
  object-fit: cover;
}
.cafe-c-pending-thumb.file {
  background: #e2e2e2;
  color: var(--c-ink-5);
}
.cafe-c-pending-info {
  min-width: 0;
  flex: 1;
}
.cafe-c-pending-name {
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-pending-size {
  color: var(--c-ink-5);
  font-size: 12px;
}
.cafe-c-format {
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--c-outline);
}
.cafe-c-editor {
  max-height: 128px;
  overflow-y: auto;
  padding: 10px 12px 4px;
}
.cafe-c-prose {
  min-height: 21px;
  outline: none;
  color: #171717;
  font-size: 14px;
  line-height: 21px;
}
.cafe-c-prose p {
  margin: 0;
}
.cafe-c-prose p.is-editor-empty:first-child::before {
  float: left;
  height: 0;
  color: var(--c-ink-4);
  content: attr(data-placeholder);
  pointer-events: none;
}
.cafe-c-prose ul,
.cafe-c-prose ol {
  margin: 0;
  padding-left: 20px;
}
.cafe-c-prose ul {
  list-style: disc;
}
.cafe-c-prose ol {
  list-style: decimal;
}
.cafe-c-prose blockquote {
  margin: 0;
  padding-left: 10px;
  border-left: 2px solid #c2c2c2;
}
.cafe-c-prose code {
  padding: 0 4px;
  border-radius: 4px;
  background: rgba(0, 0, 0, 0.08);
  font-size: 12px;
}
.cafe-c-prose pre {
  margin: 4px 0;
  padding: 8px 10px;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.08);
  font-size: 12px;
}
.cafe-c-prose pre code {
  padding: 0;
  background: none;
}
.cafe-c-prose mark {
  background: #ffe97a;
}
.cafe-c-prose a {
  text-decoration: underline;
}
.cafe-c-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 6px 6px;
}
.cafe-c-tools-left {
  display: flex;
  align-items: center;
  gap: 2px;
}
.cafe-c-tool {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: none;
  color: var(--c-ink-5);
}
.cafe-c-tool:hover:not(:disabled) {
  background: var(--c-surface);
  color: #171717;
}
.cafe-c-tool.on {
  background: #e2e2e2;
  color: #171717;
}
.cafe-c-tool:disabled,
.cafe-c-send:disabled {
  opacity: 0.5;
  cursor: default;
}
.cafe-c-sep {
  width: 1px;
  height: 16px;
  margin: 0 4px;
  background: var(--c-outline-2);
}
.cafe-c-send {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: #171717;
  color: #fff;
}
.cafe-c-send:hover:not(:disabled) {
  background: #383838;
}

/* ---- Menus, emoji, mentions (they sit on the page, not in the pane) ---- */
.cafe-c-menu,
.cafe-c-emoji,
.cafe-c-mentions {
  position: fixed;
  z-index: 70;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08), 0 8px 24px rgba(0, 0, 0, 0.12);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  color: #171717;
}
.cafe-c-menu {
  min-width: 160px;
  padding: 4px;
}
.cafe-c-menu-item {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  height: 28px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-c-menu-item:hover {
  background: var(--surface-gray-2);
}
.cafe-c-menu-item.danger {
  color: #b41d1d;
}
.cafe-c-menu .cafe-c-icon {
  color: #7c7c7c;
}
.cafe-c-menu-item.danger .cafe-c-icon {
  color: inherit;
}
.cafe-c-emoji {
  width: 288px;
  overflow: hidden;
  border-radius: 8px;
}
.cafe-c-emoji-head {
  padding: 8px;
  border-bottom: 1px solid #ededed;
}
.cafe-c-emoji-search {
  display: block;
  width: 100%;
  padding: 6px 10px;
  border: 0;
  border-radius: 4px;
  outline: none;
  background: #f3f3f3;
  color: #171717;
  font: inherit;
  font-size: 14px;
}
.cafe-c-emoji-search:focus {
  box-shadow: 0 0 0 1px #999;
}
.cafe-c-emoji-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
  max-height: 224px;
  overflow-y: auto;
  padding: 6px;
}
.cafe-c-emoji-btn {
  padding: 4px;
  border: 0;
  border-radius: 4px;
  background: none;
  font-size: 18px;
  line-height: 24px;
  cursor: pointer;
}
.cafe-c-emoji-btn:hover {
  background: #f3f3f3;
}
.cafe-c-emoji-none {
  grid-column: 1 / -1;
  margin: 0;
  padding: 24px 0;
  color: #7c7c7c;
  font-size: 13px;
  text-align: center;
}
.cafe-c-mentions {
  min-width: 200px;
  max-width: 320px;
  padding: 4px;
}
.cafe-c-mention {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-c-mention.on,
.cafe-c-mention:hover {
  background: #f3f3f3;
}
.cafe-c-mention-name {
  overflow: hidden;
  color: #7c7c7c;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Picture viewer ---- */
.cafe-c-lb {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.9);
}
.cafe-c-lb-img {
  max-width: 90vw;
  max-height: 90vh;
  object-fit: contain;
}
.cafe-c-lb-btn {
  position: absolute;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 0;
  border-radius: 9999px;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  cursor: pointer;
}
.cafe-c-lb-btn:hover {
  background: rgba(255, 255, 255, 0.2);
}
.cafe-c-lb-btn.close { top: 16px; right: 16px; }
.cafe-c-lb-btn.download { top: 16px; right: 64px; }
.cafe-c-lb-btn.prev { top: 50%; left: 16px; transform: translateY(-50%); }
.cafe-c-lb-btn.next { top: 50%; right: 16px; transform: translateY(-50%); }
.cafe-c-lb-count {
  position: absolute;
  bottom: 16px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255, 255, 255, 0.8);
  font-size: 14px;
}

/* ---- Dialogs (inside CAFE.dialog) ---- */
.cafe-dialog .cafe-c-picker,
.cafe-dialog .cafe-c-forward {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cafe-c-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.cafe-c-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 4px 4px;
  border-radius: 9999px;
  background: var(--surface-gray-2);
  font-size: 14px;
}
.cafe-c-chip-user {
  color: #7c7c7c;
}
.cafe-c-chip-x {
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: none;
  color: #7c7c7c;
  cursor: pointer;
}
.cafe-c-results {
  max-height: 192px;
  overflow-y: auto;
  border: 1px solid var(--outline-gray-1);
  border-radius: 6px;
}
.cafe-c-results.tall {
  max-height: 288px;
}
.cafe-c-results-note {
  margin: 0;
  padding: 12px;
  color: #7c7c7c;
  font-size: 13px;
  text-align: center;
}
.cafe-c-pick {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border: 0;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-c-pick:hover {
  background: #f8f8f8;
}
.cafe-c-pick-text {
  min-width: 0;
  flex: 1;
}
.cafe-c-pick-user {
  margin-left: 6px;
  color: #7c7c7c;
  font-size: 12px;
}
.cafe-c-hint {
  margin: 0 0 8px;
  color: #7c7c7c;
  font-size: 13px;
}
.cafe-c-poll-inputs {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cafe-c-poll-input {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cafe-c-poll-input input {
  flex: 1;
}
.cafe-c-add-option {
  margin-top: 8px;
}
.cafe-c-check {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 10px;
  font-size: 14px;
}
.cafe-c-group {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.cafe-c-group-title {
  margin: 0;
  font-size: 14px;
}
.cafe-c-members {
  border: 1px solid var(--outline-gray-1);
  border-radius: 6px;
}
.cafe-c-members > * + * {
  border-top: 1px solid var(--outline-gray-1);
}
.cafe-c-member {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
}
.cafe-c-member-text {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 6px;
}
.cafe-c-member-name {
  overflow: hidden;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.cafe-c-member-name.grow {
  flex: 1;
}
.cafe-c-badge {
  padding: 1px 6px;
  border-radius: 6px;
  background: var(--surface-gray-2);
  color: #525252;
  font-size: 11px;
}

/* ---- Phone: the list and the conversation are separate screens ---- */
@media (max-width: 767px) {
  /* As in the old page, which is 52px shorter than the screen and sits under the bottom bar. */
  .cafe-chat-main {
    flex-grow: 0 !important;
    height: calc(100vh - 52px) !important;
  }
  .cafe-c-head-left {
    gap: 4px;
  }
  html[data-chat-view='thread'] .cafe-chat-mobile-head {
    display: none !important;
  }
  #cafe-chat .cafe-c-list {
    flex-basis: 100%;
    width: 100%;
    border-right: 0;
  }
  #cafe-chat[data-view='thread'] .cafe-c-list,
  #cafe-chat[data-view='list'] .cafe-c-thread {
    display: none;
  }
  .cafe-c-back {
    display: grid;
  }
  .cafe-c-msg-col {
    max-width: 80%;
  }
}
